if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_iface() {
    if command -v ip >/dev/null 2>&1; then
        ip -o link show 2>/dev/null | gawk -F': ' '{ sub(/@.*/, "", $2); print $2 }'
        return 0
    fi
    if [[ -d /sys/class/net ]]; then
        find /sys/class/net -mindepth 1 -maxdepth 1 | sed 's|.*/||'
    fi
}

_choice_ip_options() {
    printf 'R\trecord route\n'
    printf 'S\tstrict source route\n'
    printf 'L\tloose source route\n'
    printf 'T\trecord timestamp\n'
}

_choice_output_basename() {
    _argc_util_comp_path
}

_choice_port() {
    [[ -r /etc/services ]] || return 0
    gawk '!/^#/ && NF >= 2 { printf "%s\t%s\n", $1, $2 }' /etc/services
}

_choice_protocol() {
    [[ -r /etc/protocols ]] || return 0
    gawk '!/^#/ && NF >= 2 { printf "%s\t%s\n", $1, $2 }' /etc/protocols
}

_choice_scanflags() {
    printf 'URG\turgent pointer\n'
    printf 'ACK\tacknowledgment\n'
    printf 'PSH\tpush\n'
    printf 'RST\treset\n'
    printf 'SYN\tsynchronize\n'
    printf 'FIN\tfinish\n'
    printf 'ALL\tall flags\n'
    printf 'NONE\tno flags\n'
}

_choice_script() {
    printf '%s\n' auth broadcast brute default discovery dos exploit external fuzzer intrusive malware safe version vuln
    nmap --script-help all 2>/dev/null | gawk '
        /^Categories:/ {
            if (name != "") {
                print name
            }
            name = ""
            next
        }
        /^[[:alnum:]_.-]+$/ {
            name = $0
        }
    '
}

_choice_stylesheet() {
    _argc_util_comp_path
}

_choice_t() {
    printf '0\tparanoid\n1\tsneaky\n2\tpolite\n3\tnormal\n4\taggressive\n5\tinsane\n'
}

_choice_version_intensity() {
    printf '0\tlight\n'
    printf '%s\n' 1 2 3 4 5 6 7 8
    printf '9\ttry all probes\n'
}
